import { PRESET_IDS, getPreset } from '../presets';
import { parseDate } from '../time';
import type { QueryError } from './ast';
import { lineCol } from './lexer';
import { type ParamUnit, suggest } from './parser';
import type { QueryInput } from './query';

export type QueryDocument = QueryInput & {
  preset: string | null;
  from: string | null;
  to: string | null;
  tie: 'miss' | 'hit' | 'exclude' | null;
};

const KEYS = ['setup', 'outcome', 'param', 'preset', 'from', 'to', 'tie'];
const KEY_LIST = 'Keys are setup, outcome, param, preset, from, to and tie.';

export function parseQueryDocument(text: string): { ok: true; input: QueryDocument } | { ok: false; errors: QueryError[] } {
  const errors: QueryError[] = [];
  const err = (code: string, offset: number, length: number, message: string): void => {
    const { line, column } = lineCol(text, offset);
    errors.push({ code, part: 'document', offset, length: Math.max(1, length), line, column, message });
  };
  const fields: Record<string, string> = {};
  const params: Record<string, number> = {};
  const paramUnits: Record<string, ParamUnit> = {};
  let current: 'setup' | 'outcome' | null = null;
  let offset = 0;
  for (const raw of text.split('\n')) {
    const lineStart = offset;
    offset += raw.length + 1;
    const line = raw.endsWith('\r') ? raw.slice(0, -1) : raw;
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    if (/^\s/.test(line) && current) {
      fields[current] += ' ' + trimmed;
      continue;
    }
    current = null;
    const m = /^\s*([A-Za-z_]+)\s*:(.*)$/.exec(line);
    if (!m) {
      err('E_UNKNOWN_KEY', lineStart + (line.length - line.trimStart().length), trimmed.length, `'${trimmed}' is not a query document key. ${KEY_LIST}`);
      continue;
    }
    const key = m[1].toLowerCase();
    const value = m[2].trim();
    const valueOffset = lineStart + line.indexOf(':') + 1 + (m[2].length - m[2].trimStart().length);
    if (!KEYS.includes(key)) {
      err('E_UNKNOWN_KEY', lineStart + line.indexOf(m[1]), m[1].length, `'${m[1]}' is not a query document key. ${KEY_LIST}`);
      continue;
    }
    if (key === 'param') {
      const pm = /^\$?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(-?[0-9]+(?:\.[0-9]+)?)\s*(%|pts)?$/.exec(value);
      if (!pm) {
        err('E_EXPECTED', valueOffset, value.length, `Expected name = value at column ${lineCol(text, valueOffset).column}, found '${value}'.`);
        continue;
      }
      const name = pm[1].toLowerCase();
      if (name in params) {
        err('E_DUPLICATE_KEY', lineStart, line.length, `The query document already has a param ${name} line.`);
        continue;
      }
      params[name] = Number(pm[2]);
      paramUnits[name] = pm[3] === '%' ? '%' : pm[3] === 'pts' ? 'points' : 'none';
      continue;
    }
    if (key in fields) {
      err('E_DUPLICATE_KEY', lineStart, line.length, `The query document already has a ${key} line.`);
      continue;
    }
    fields[key] = value;
    if (key === 'setup' || key === 'outcome') current = key;
    if ((key === 'from' || key === 'to') && parseDate(value) === null) err('E_BAD_DATE', valueOffset, value.length, `'${value}' is not a date. Write YYYY-MM-DD.`);
    if (key === 'tie' && !['miss', 'hit', 'exclude'].includes(value.toLowerCase()))
      err('E_EXPECTED', valueOffset, value.length, `Expected miss, hit or exclude at column ${lineCol(text, valueOffset).column}, found '${value}'.`);
    if (key === 'preset' && !getPreset(value)) err('E_UNKNOWN_PRESET', valueOffset, value.length, `There is no preset '${value}'.${suggest(value, PRESET_IDS)}`);
  }
  const preset = fields.preset !== undefined ? getPreset(fields.preset) : null;
  if (!errors.length && !preset) {
    if (fields.setup === undefined) err('E_EMPTY', text.length, 1, 'The setup is empty.');
    if (fields.outcome === undefined) err('E_EMPTY', text.length, 1, 'The outcome is empty.');
  }
  if (errors.length) return { ok: false, errors };
  return {
    ok: true,
    input: {
      setup: fields.setup ?? preset!.setup,
      outcome: fields.outcome ?? preset!.outcome,
      params,
      paramUnits,
      preset: preset ? preset.id : null,
      from: fields.from ?? null,
      to: fields.to ?? null,
      tie: fields.tie ? (fields.tie.toLowerCase() as 'miss' | 'hit' | 'exclude') : null,
    },
  };
}
